import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';

// @spec specs/hal-engine-config-hooks/spec.md#11
it('reports both provider calls when a tool completes a turn', async () => {
  const rounds: MessageChunk[][] = [
    [
      {type: 'tool_use', toolCall: {id: 'echo-1', name: 'echo', input: {}}},
      {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 4, outputTokens: 2, totalTokens: 6}},
    ],
    [{type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 9, outputTokens: 3, totalTokens: 12}}],
  ];
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds.shift() ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      throw new Error('Structured output is outside this provider contract.');
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'echo', description: 'Echo.', inputSchema: {type: 'object'}}, async () => 'echo');
  let reported: UsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Usage contract.'}), registry, {
    hooks: {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    },
  });

  await orchestrator.processMessage({
    sessionId: 'contract-session',
    userId: 'contract-user',
    entries: [{role: 'user', content: 'Echo.', timestamp: '2026-01-01T00:00:00.000Z'}],
  });

  expect(reported).toEqual({inputTokens: 13, outputTokens: 5, totalTokens: 18});
});
import type {UsageMetadata} from '../types/ai.js';

export function accumulateUsage(
  total: UsageMetadata | undefined,
  round: UsageMetadata | undefined
): UsageMetadata | undefined {
  if (!round) return total;
  if (!total) return round;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}
